            clean_and_split(row, text_column);
        }
    }
}

void clean_and_split(string& text, string column_name) {
    // 特殊文字削除
    text.erase(remove_if(text.begin(), text.end(), [](unsigned char c) {
        return !isalnum(c) && c != ' ';
    }), text.end());

    // 単語分割
    vector<string> words;
    istringstream iss(text);
    while (iss >> word) {
        words.push_back(word);
    }
    text = join(words, " ");
}

