/**
 * 重複行を削除し、最初に登場した行のみを残す。
 * 'ユーザーID'と'商品名'が重複の条件とする。
 */
void remove_duplicate(vector<string>& df_rows, string user_id, string product_name) {
    // 重複行を排除するためのソート関数
    sort(df_rows.begin(), df_rows.end(), [](const string& a, const string& b) {
        return (a[user_id] < b[user_id]) || 
               (a[user_id] == b[user_id] && a[product_name] <= b[product_name]);
    });

    // 最後の非重複行を取得し、後から全部削除
    auto last = unique(df_rows.begin(), df_rows.end());
    df_rows.erase(last, df_rows.end());
}

/**
 * 欠失値を0埋めする。
 */
void fillna(vector<string>& df_rows, int value) {
    for (auto& row : df_rows) {
        // 空白を'value'に代入
        replace_all(row, ' ', to_string(value));
    }
}

/**
 * データ行に'日付'の列があるか否かを確認する。
 */
bool contains_time_column(const vector<string>& df_rows) {
    if (df_rows.empty()) return false;

    // 初期行を分解し、各列名をチェック
    string header = df_rows[0];
    size_t pos = header.find('}');
    string date_header = header.substr(0, pos);

    return (date_header == "日付");
}

/**
 * '日付'列を文字形式からdatetime形式に変換する。
 */
void convert_to_datetime(vector<string>& df_rows, string date_column) {
    for (auto& row : df_rows) {
        if (row.find(date_column) != string::npos) {
            // 日付形式を正規化
            row = datetime_to_string(row);
        }
    }
}

/**
 * 'チャット内容'列の文本をクリーニングする。
 */
void clean_text(vector<string>& df_rows, string text_column) {
    for (auto& row : df_rows) {
        if (row.find(text_column) != string::npos) {
            // 特殊文字を削除し、単語を分割
            clean_and_split(row, text_column);
        }
    }
}

/**
 * 'チャット内容'の文本をクリーニングし、単語に分割する。
 */
void clean_and_split(string& text, string column_name) {
    // 特殊文字削除
    text.erase(remove_if(text.begin(), text.end(), [](unsigned char c) {
        return !isalnum(c) && c != ' ';
    }), text.end());

    // 単語分割
    vector<string> words;
    istringstream iss(text);
    while (iss >> word) {
        words.push_back(word);
    }
    // 分割された単語を再合成
    text = join(words, " ");
}

/**
 * グラフ作成の関数（トレンドグラフの例）
 */
void draw_trend_graph(const vector<string>& sales_data) {
    if (sales_data.empty()) return;

    // 日付を独自に管理するデータフレームを作成
    vector<string> unique_dates = get_unique_dates(sales_data);
    vector<double> sales_values = get_sales_values(sales_data, unique_dates);

    plt.figure(figsize=(10,6));
    plot_dates(unique_dates, sales_values, "Daily Sales");
    plt.xlabel("Date");
    plt.ylabel("Sales Amount");
    plt.title("Sales Trend");
    plt.legend();
    plt.show();
}

/**
 * 日付を含むデータから唯一の日付を取得する。
 */
vector<string> get_unique_dates(const vector<string>& sales_data) {
    vector<string> unique_dates;

    // 日付列を抽出
    vector<string> date_columns;
    for (const string& row : sales_data) {
        if (row.find("日付") != string::npos) {
            date_columns.push_back(row);
        }
    }

    // 日付を含む行を抽出
    for (string& row : sales_data) {
        if (row.find("日付") != string::npos) {
            unique_dates.push_back(get_date_str(row));
        }
    }

    return unique_dates;
}

/**
 * 日付形式を正規化し、'YYYY-MM-DD'の形式で返す。
 */
string get_date_str(const string& date_string) {
    // 日付文字列から年月日を抽出
    string format_str = "%Y-%m-%d";
    size_t pos = date_string.find("日");
    return datetime_from_string(date_string.substr(0, pos), format_str);
}

