            double sales = get_sales_value(row);
            int purchases = get_purchases_count(row);
            int product_rank = get_product_rank(row);

            report_lines.push_back(to_string(sales) + "," + to_string(purchases) + "," + to_string(product_rank));
        }

        // ファイルに書き込む
        ofstream ofs(report_path.c_str());
        for (const string& line : report_lines) {
            ofs << line << endl;
        }
        ofs.close();
    }
}

