        string cleaned = regex_replace(re, "", text);
        cleaned.erase(remove_if(cleaned.begin(), cleaned.end(), ::isspace), cleaned.end());
        if (!cleaned.empty()) {
            clean_texts.push_back( join(split(cleaned, ' '), 1) );
