        if (entry.path().extension() == "csv") {
            files.push_back(entry.path().string());
        }
    }
    return files;
}

void runProcessing() {
    atomic<bool> running(true);
    signal(SIGINT, [](int) { running = false; });

    vector<string> all_files = getDataFiles();
    vector<vector<string>> chunks;

    // Divide files into chunks for processing
    int chunk_size = 10000;
    int total_chunks = all_files.size() / chunk_size;

    queue<int> progress(0, total_chunks);

    // Use a mutex to protect shared data
    mutex lock;

    vector<string> results;

    while (running) {
        if (!progress.empty()) {
            int current_chunk = progress.front();
            progress.pop();

            vector<string> chunk_files;
            for (int i = current_chunk*chunk_size; 
                  i < min((current_chunk+1)*chunk_size, all_files.size()); ++i) {
                chunk_files.push_back(all_files[i]);
            }

            if (!chunk_files.empty()) {
                thread t(processChunk, chunk_files, results);
                t.detach();

                // Show progress in console
                cout << "Processing chunk " << (current_chunk+1) << " of " << total_chunks 
                     << endl;
            } else {
                this_thread::sleep_for(chrono::milliseconds(100));
            }
        } else if (!results.empty()) {
            size_t processed = 0;
            for (const auto& res : results) {
                if (res[0] == -1) continue;

                string table_name = "daily_sales_revenue";
                storeResults(res, table_name, "customer_analytics", 
                            "localhost", "analytics_user", "password");

                processed++;
            }
            cout << "Finished processing all chunks (" << processed << ")" << endl;
        } else {
            this_thread::sleep_for(chrono::milliseconds(100));
        }
    }

    // Wait for all threads to finish
    while (!running) { this_thread::sleep_for(chrono::seconds(1)); }
}

int main() {
    try {
        // Initialize logging (simplified here)
        cout << "Customer analytics processing started" << endl;

        runProcessing();

        return 0;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return -1;
    }
}
